(() => {const form=document.querySelector('#inquiry-form');if(!form)return;form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const values=new FormData(form);const target=document.querySelector('.email')?.getAttribute('href')||'mailto:wntec@daum.net';const email=target.startsWith('mailto:')?target.split('?')[0]:'mailto:wntec@daum.net';const subject='[위닝텍 제작 상담] '+values.get('company')+' / '+values.get('category');const body=['회사명: '+values.get('company'),'담당자: '+values.get('contact'),'이메일: '+values.get('email'),'연락처: '+values.get('phone'),'문의 분야: '+values.get('category'),'','문의 내용:',values.get('message')].join('\n');location.href=email+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);document.querySelector('#inquiry-status').textContent='이메일 앱에서 내용을 확인하고 전송해주세요. 앱이 열리지 않으면 위 연락처로 문의해주세요.';});})();
